using System.Text.RegularExpressions;
using Application.Common;

namespace Infrastructure.Storage;

public sealed class StorageSettings
{
    /// <summary>Folder for uploaded files. Keep it outside any web root and out of source control.</summary>
    public string LocalRoot { get; set; } = ".data/media";
    /// <summary>URL path the API serves stored files from.</summary>
    public string PublicPath { get; set; } = "/media";
}

/// <summary>Keeps files on local disk. Keys are generated by the application, never taken from a client.</summary>
public sealed partial class LocalDiskFileStorage(StorageSettings settings) : IFileStorage
{
    private readonly string root = Path.GetFullPath(settings.LocalRoot);

    [GeneratedRegex("^[a-z0-9]+(?:/[a-z0-9-]+)*\\.(?:webp|jpe?g|png)$")]
    private static partial Regex KeyPattern();

    public string Root => root;

    public async Task SaveAsync(string key, Stream content, string contentType, CancellationToken cancellationToken)
    {
        var path = Resolve(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temp = path + ".tmp";
        await using (var file = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None))
            await content.CopyToAsync(file, cancellationToken);
        File.Move(temp, path, overwrite: false);
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken)
    {
        var path = Resolve(key);
        return Task.FromResult<Stream?>(File.Exists(path) ? File.OpenRead(path) : null);
    }

    public Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        var path = Resolve(key);
        if (File.Exists(path)) File.Delete(path);
        return Task.CompletedTask;
    }

    public string GetPublicUrl(string key) => settings.PublicPath.TrimEnd('/') + "/" + Validate(key);

    private string Resolve(string key)
    {
        var path = Path.GetFullPath(Path.Combine(root, Validate(key)));
        if (!path.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
            throw new InvalidOperationException("Storage key resolves outside the storage root.");
        return path;
    }

    private static string Validate(string key) =>
        KeyPattern().IsMatch(key) ? key : throw new InvalidOperationException("Invalid storage key.");
}
